test("001 - TC-001 — Verify GET /users/1 returns 200 with a non-empty JSON user object", async ({ request }) => {
  const usersApi = new UsersApi(request);

  console.log("\n▶ TC-001 — Verify GET /users/1 returns 200 with a non-empty JSON user object");
  console.log('  → request:', "GET https://jsonplaceholder.typicode.com/users/1");

  const response = await usersApi.verifyGETUsers1Returns200WithANonEmptyJSON();
  console.log('  ← response:', response.status(), '·', usersApi.durationMs + 'ms');
  const body = await usersApi.json(response);

  console.log('   ↳ assert:', "response status is 200", '| actual =', response.status());
  expect(response.status(), 'HTTP status code').toBe(200);
  console.log('   ↳ assert:', "header \"content-type\" contains \"application/json\"", '| actual =', String(response.headers()["content-type"] || ''));
  expect(String(response.headers()["content-type"] || ''), "header \"content-type\" should contain \"application/json\"").toContain("application/json");
  console.log('   ↳ assert:', "JSON \"id\" is present", '| actual =', getPath(body, "id"));
  expect(getPath(body, "id"), "property \"id\" should exist").toBeDefined();
  console.log('   ↳ assert:', "response time is under 5000 ms", '| actual =', usersApi.durationMs);
  expect(usersApi.durationMs, 'response time (ms)').toBeLessThan(5000);

  console.log("  ✓ TC-001: all 4 assertions passed");
});

